// Package cragent holds the files at the root of the repository that are compiled into the agent:
// the engine pin and the architecture list generated from it.
package cragent

import _ "embed"

// EngineLock is engine.lock: the pinned llama.cpp tag, the official zips with their SHA-256, and the
// allow-list of engine output lines that may reach the agent log (ruling B16).
//
//go:embed engine.lock
var EngineLock []byte

// SupportedArchs is supported_archs.txt, generated by tools/genarchs from the pinned tag.
//
//go:embed supported_archs.txt
var SupportedArchs string

// Changelog is CHANGELOG.md, which the tray shows under What's new.
//
//go:embed CHANGELOG.md
var Changelog string
